impl CliConfig {
    pub fn new() -> Self {
        Self {
            output: String::from("default"),
            verbose: false,
        }
    }

    /// Builds a config from command-line arguments (program name excluded).
    pub fn from_args<I, S>(args: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let mut config = Self::new();
        for arg in args {
            if arg.as_ref() == "--verbose" {
                config.verbose = true;
            }
        }
        config
    }
}

