        assert!(CliConfig::from_args(["--verbose"]).verbose);
    }

    #[test]
    fn from_args_defaults_to_not_verbose() {
        assert!(!CliConfig::from_args(Vec::<String>::new()).verbose);
        assert!(!CliConfig::from_args(["other"]).verbose);
    }
}
